insert into drinks (id, slug, name, name_en, category, description, emoji) values ('d-iced-americano', 'iced-americano', '아이스 아메리카노', 'Iced Americano', 'coffee', '에스프레소 샷에 물과 얼음을 더한 기본 커피. 브랜드별 샷 수와 용량 차이가 가장 뚜렷한 메뉴.', '🧊') on conflict (id) do update set slug = excluded.slug, name = excluded.name, name_en = excluded.name_en, category = excluded.category, description = excluded.description, emoji = excluded.emoji;
insert into drinks (id, slug, name, name_en, category, description, emoji) values ('d-hot-americano', 'americano', '아메리카노', 'Americano', 'coffee', '에스프레소 샷에 뜨거운 물을 더한 커피의 기본. 원두 로스팅 차이가 그대로 드러난다.', '☕') on conflict (id) do update set slug = excluded.slug, name = excluded.name, name_en = excluded.name_en, category = excluded.category, description = excluded.description, emoji = excluded.emoji;
insert into drinks (id, slug, name, name_en, category, description, emoji) values ('d-cold-brew', 'cold-brew', '콜드브루', 'Cold Brew', 'coffee', '찬물로 장시간 추출해 산미가 적고 부드러운 커피. 추출 방식과 원액 비율이 브랜드별로 다르다.', '🫗') on conflict (id) do update set slug = excluded.slug, name = excluded.name, name_en = excluded.name_en, category = excluded.category, description = excluded.description, emoji = excluded.emoji;
insert into drinks (id, slug, name, name_en, category, description, emoji) values ('d-cafe-latte', 'cafe-latte', '카페라떼', 'Cafe Latte', 'latte', '에스프레소와 스팀 밀크의 조합. 우유 비율과 샷 수가 고소함을 좌우한다.', '🥛') on conflict (id) do update set slug = excluded.slug, name = excluded.name, name_en = excluded.name_en, category = excluded.category, description = excluded.description, emoji = excluded.emoji;
